//! A writer for Rust source. Indentation and braces come from the structure of the calls.

use alloc::string::String;

use crate::ident::{Error, is_ident, string_literal};

const INDENT: &str = "    ";

/// Builds Rust source text. Blocks are written with a closure, so braces always balance.
///
/// Identifiers are checked, and string values are escaped. The first error is
/// kept, and [`Writer::finish`] returns it.
///
/// ```
/// use tpt_dev_codegen::Writer;
///
/// let mut w = Writer::new();
/// w.line("// generated by build.rs");
/// w.blank();
/// w.constant("pub", "MAX_CHANNELS", "u8", "8").unwrap();
/// w.block("pub fn channel_name(index: u8) -> &'static str", |w| {
///     w.line("const NAMES: [&str; 2] = [\"left\", \"right\"];");
///     w.line("NAMES[index as usize % 2]");
/// });
/// let src = w.finish().unwrap();
/// assert!(src.contains("    NAMES[index as usize % 2]"));
/// ```
#[derive(Debug, Default)]
pub struct Writer {
    out: String,
    depth: usize,
    error: Option<Error>,
}

impl Writer {
    /// An empty writer.
    pub const fn new() -> Self {
        Self {
            out: String::new(),
            depth: 0,
            error: None,
        }
    }

    /// Writes one line at the current indentation.
    pub fn line(&mut self, text: &str) -> &mut Self {
        for _ in 0..self.depth {
            self.out.push_str(INDENT);
        }
        self.out.push_str(text);
        self.out.push('\n');
        self
    }

    /// Writes an empty line.
    pub fn blank(&mut self) -> &mut Self {
        self.out.push('\n');
        self
    }

    /// Writes `header {`, runs `body` one level deeper, then writes `}`.
    pub fn block<F>(&mut self, header: &str, body: F) -> &mut Self
    where
        F: FnOnce(&mut Self),
    {
        let opening = alloc::format!("{header} {{");
        self.line(&opening);
        self.depth += 1;
        body(self);
        self.depth -= 1;
        self.line("}");
        self
    }

    /// Writes `visibility const NAME: ty = value;`. The name is checked. The
    /// value is written as given, so it must be a valid expression.
    pub fn constant(
        &mut self,
        visibility: &str,
        name: &str,
        ty: &str,
        value: &str,
    ) -> Result<&mut Self, Error> {
        if !is_ident(name) {
            return Err(self.fail(alloc::format!("`{name}` is not a valid constant name")));
        }
        let text = if visibility.is_empty() {
            alloc::format!("const {name}: {ty} = {value};")
        } else {
            alloc::format!("{visibility} const {name}: {ty} = {value};")
        };
        self.line(&text);
        Ok(self)
    }

    /// Writes a `&'static str` constant, with the value escaped.
    pub fn str_constant(
        &mut self,
        visibility: &str,
        name: &str,
        value: &str,
    ) -> Result<&mut Self, Error> {
        let literal = string_literal(value);
        self.constant(visibility, name, "&'static str", &literal)
    }

    /// Records an error for a bad identifier, and returns it.
    fn fail(&mut self, message: String) -> Error {
        let e = Error { message };
        if self.error.is_none() {
            self.error = Some(e.clone());
        }
        e
    }

    /// The generated source, or the first error that occurred.
    pub fn finish(self) -> Result<String, Error> {
        match self.error {
            Some(e) => Err(e),
            None => Ok(self.out),
        }
    }
}

#[cfg(test)]
#[allow(clippy::unwrap_used)]
mod tests {
    use super::*;

    #[test]
    fn nested_blocks_are_indented() {
        let mut w = Writer::new();
        w.block("mod m", |w| {
            w.block("fn f()", |w| {
                w.line("1");
            });
        });
        assert_eq!(
            w.finish().unwrap(),
            "mod m {\n    fn f() {\n        1\n    }\n}\n"
        );
    }

    #[test]
    fn bad_constant_name_is_an_error() {
        let mut w = Writer::new();
        assert!(w.constant("", "not valid", "u8", "1").is_err());
        assert!(w.finish().is_err());
    }

    #[test]
    fn string_constants_are_escaped() {
        let mut w = Writer::new();
        w.str_constant("pub", "GREETING", "say \"hi\"").unwrap();
        assert_eq!(
            w.finish().unwrap(),
            "pub const GREETING: &'static str = \"say \\\"hi\\\"\";\n"
        );
    }
}
